/**
 * LobuRef — one portable, typed reference to any first-class object the UI can
 * point at: an entity, connection, connector, feed, watcher, member, or event.
 * The reference picker emits these, and the chat composer serializes them into
 * a message so an agent turn can be told "this is about <that object>".
 *
 * Inline wire form (rides inside an ordinary message `content` string — no new
 * API field):
 *
 *   @[entity:Spotify](/acme/company/spotify)
 *   @[connection:Stripe prod](/acme/connectors/stripe/42)
 *
 * `kind`  — object family (drives worker-side expansion).
 * `id`    — stable id as a string (entity id, connection id, watcher uuid,
 *           connector key, member user id, event id).
 * `path`  — frontend route to the object; makes the chip clickable and lets the
 *           ref be re-resolved (entities via resolve_path, others via their API).
 * `label` — display name captured at pick time (what the chip shows).
 */

export type LobuRefKind =
	| "entity"
	| "connection"
	| "connector"
	| "feed"
	| "behavior"
	| "member"
	| "metric"
	| "sql"
	| "event";

export const LOBU_REF_KINDS: readonly LobuRefKind[] = [
	"entity",
	"connection",
	"connector",
	"feed",
	"behavior",
	"member",
	"metric",
	"sql",
	"event",
] as const;

export interface LobuRef {
	kind: LobuRefKind;
	id: string;
	path: string;
	label: string;
}

interface BehaviorSource {
	name: string;
	query: string;
}

function isLobuRefKind(value: string): value is LobuRefKind {
	return (LOBU_REF_KINDS as readonly string[]).includes(value);
}

/** One inline ref token: `@[kind:id:label](path)`. Groups: kind, id, label,
 *  path. id = any char except `:`/`]` (a controlled slug); label = any char
 *  except `]`; path = any char except `)` / whitespace (0+, so an empty `()` is
 *  valid — a synthetic SQL action carries no path). Embedding the id lets
 *  callers recover the object's stable identifier (e.g. a feed_key or
 *  `type.measure`) from the token alone — needed to compile watcher sources.
 *
 *  This grammar is mirrored by the server in `watchers/source-refs.ts`, which
 *  the owletto submodule cannot import. Keep both copies in sync. */
const REF_TOKEN = /@\[([a-z]+):([^:\]]*):([^\]]*)\]\(([^)\s]*)\)/g;

/** Serialize one ref to its inline token. Brackets/colons are stripped from the
 *  label so the token stays unambiguous. */
export function serializeRef(ref: LobuRef): string {
	const safeLabel = ref.label.replace(/[[\]]/g, "").trim();
	const safeId = ref.id.replace(/[[\]:]/g, "");
	return `@[${ref.kind}:${safeId}:${safeLabel}](${ref.path})`;
}

