1	/**
2	 * Behavior instruction compile — the web mirror of `lobu apply`.
3	 *
4	 * A Behavior has no author-facing prompt (issue #2320). Instructions are the
5	 * ordered skill bodies of the owning agent, joined at save time and frozen into
6	 * the version. The server never sees `skills[]` — it stores only the compiled
7	 * text — so this module and the CLI's `compileBehaviorInstructions`
8	 * (`packages/cli/src/commands/_lib/apply/desired-state.ts`) must agree
9	 * byte-for-byte, or the same Behavior authored in the two surfaces would freeze
10	 * different instructions and churn versions against each other.
11	 *
12	 * The freeze is the honest part of the model: editing a skill afterwards does
13	 * NOT change an existing Behavior until it is saved again (an accepted limit in
14	 * #2320). Copy in the picker says so rather than implying a live link.
15	 */
16	
17	/** Max skills a Behavior may reference. Mirrors `MAX_BEHAVIOR_SKILLS` (CLI). */
18	export const MAX_BEHAVIOR_SKILLS = 5;
19	
20	/** Compiled-instruction ceiling. Mirrors `MAX_COMPILED_INSTRUCTIONS_BYTES`. */
21	export const MAX_COMPILED_INSTRUCTIONS_BYTES = 32 * 1024;
22	
23	/** A skill the picker can offer: a library entry with a usable body. */
24	export interface BehaviorSkillOption {
25		name: string;
26		description?: string;
27		/**
28		 * Authored body. Custom skills carry `content`; bundled/system skills carry
29		 * the catalog's `instructions`. The CLI only ever resolves files into
30		 * `content`, so it has no equivalent fallback.
31		 */
32		content?: string;
33		instructions?: string;
34		enabled: boolean;
35	}
36	
37	/** The body a skill contributes to the compile, or "" when it has none. */
38	export function skillBody(skill: BehaviorSkillOption): string {
39		return (skill.content ?? skill.instructions ?? "").trim();
40	}
41	
42	/** Skills that can actually be compiled: enabled and carrying a body. */
43	export function selectableSkills(
44		library: BehaviorSkillOption[],
45	): BehaviorSkillOption[] {
46		return library.filter((skill) => skill.enabled && skillBody(skill) !== "");
47	}
48	
49	/** Trigger shape this module needs. Extra keys are ignored. */
50	export interface BehaviorTriggerLike {
51		kind?: string;
52		execution?: string;
53	}
54	
55	/**
56	 * Whether the Behavior runs on its compiled instructions alone.
57	 *
58	 * An event trigger executing as "turn" carries its own content (the incoming
59	 * message/event) and may run with zero skills on the built-in default.
60	 * Everything else — schedule triggers, event triggers with execution "window",
61	 * and Behaviors with no triggers at all (manual runs) — has nothing but its
62	 * instructions, so it needs at least one skill. Mirrors `assertBehaviorSkills`.
63	 */
64	export function behaviorRequiresSkills(
65		triggers: BehaviorTriggerLike[] | undefined,
66	): boolean {
67		const list = triggers ?? [];
68		if (list.length === 0) return true;
69		return list.some(
70			(trigger) => trigger.kind === "schedule" || trigger.execution === "window",
71		);
72	}
73	
74	/**
75	 * Join the selected skill bodies in order. Returns "" for an empty selection —
76	 * the event-turn case, where the server applies its built-in default.
77	 */
78	export function compileBehaviorInstructions(
79		selected: string[],
80		library: BehaviorSkillOption[],
81	): string {
82		if (selected.length === 0) return "";
83		const byName = new Map(library.map((skill) => [skill.name, skill]));
84		const bodies: string[] = [];
85		for (const name of selected) {
86			const skill = byName.get(name);
87			const body = skill ? skillBody(skill) : "";
88			if (body) bodies.push(body);
89		}
90		return bodies.join("\n\n");
91	}
92	
93	/** UTF-8 byte length of the compiled text (the cap is bytes, not characters). */
94	export function compiledByteLength(compiled: string): number {
95		return new TextEncoder().encode(compiled).length;
96	}
97	
98	/**
99	 * Validate a selection against the same rules `lobu apply` enforces, so the web
100	 * cannot author a Behavior the CLI would reject. Returns null when valid.
101	 */
102	export function validateBehaviorSkills(
103		selected: string[],
104		library: BehaviorSkillOption[],
105		triggers: BehaviorTriggerLike[] | undefined,
106	): string | null {
107		const duplicates = selected.filter((name, i) => selected.indexOf(name) !== i);
108		if (duplicates.length > 0) {
109			return `Duplicate skill: ${[...new Set(duplicates)].join(", ")} — the compile is ordered, so each skill may appear once.`;
110		}
111		if (selected.length > MAX_BEHAVIOR_SKILLS) {
112			return `${selected.length} skills selected — the maximum is ${MAX_BEHAVIOR_SKILLS}.`;
113		}
114		const byName = new Map(library.map((skill) => [skill.name, skill]));
115		for (const name of selected) {
116			const skill = byName.get(name);
117			if (!skill) {
118				return `Skill "${name}" is no longer in this agent's library.`;
119			}
120			if (!skill.enabled) {
121				return `Skill "${name}" is disabled — enable it on the agent or remove it here.`;
122			}
123			if (skillBody(skill) === "") {
124				return `Skill "${name}" has an empty body — compiled instructions need text.`;
125			}
126		}
127		if (behaviorRequiresSkills(triggers) && selected.length === 0) {
128			return "Add at least one skill: schedules, window triggers, and Behaviors with no trigger run on their compiled instructions alone.";
129		}
130		const bytes = compiledByteLength(
131			compileBehaviorInstructions(selected, library),
132		);
133		if (bytes > MAX_COMPILED_INSTRUCTIONS_BYTES) {
134			return `These skills compile to ${Math.round(bytes / 1024)}KB of instructions — the maximum is ${MAX_COMPILED_INSTRUCTIONS_BYTES / 1024}KB.`;
135		}
136		return null;
137	}
