1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { useOrgContext } from "@/hooks/use-org-context";
3	import { useReferenceSearch } from "@/lib/api/references";
4	import type { LobuRef, LobuRefKind } from "@/lib/references";
5	
6	/**
7	 * useMentionSearch — bridges the async React `useReferenceSearch` hook to the
8	 * imperative `searchRefs(query) => Promise<LobuRef[]>` that a Tiptap suggestion
9	 * plugin needs. Shared by the chat composer and the watcher prompt editor.
10	 *
11	 * A suggestion request sets the query state (driving the search); the promise
12	 * resolves once results for that exact query are ready — including the
13	 * "reopened with the same query" case, where no state change fires and the data
14	 * is already cached, so we resolve from the mirror immediately.
15	 */
16	export function useMentionSearch(kinds: LobuRefKind[], limitPerKind = 5) {
17		const { currentOwner, resolvedOrganizationId } = useOrgContext();
18		const [query, setQuery] = useState<string | null>(null);
19		// Keep the underlying entity/connection/… lists enabled from mount so they're
20		// warm before the user types `@`. Gating the fetch on `query !== null` was a
21		// lazy-load that made the FIRST `@query` resolve against a cold cache — the
22		// data hadn't loaded, so `refs` was `[]` and the popup came up empty. The
23		// text filter is applied synchronously in `refs`, so eager-loading the lists
24		// costs one small fetch on mount and makes the popup reliable.
25		const { refs, isLoading } = useReferenceSearch({
26			owner: currentOwner,
27			organizationId: resolvedOrganizationId,
28			kinds,
29			query: query ?? "",
30			limitPerKind,
31		});
32	
33		// Live mirrors so the resolver sees fresh values without stale closures.
34		const refsRef = useRef<LobuRef[]>([]);
35		refsRef.current = refs;
36		const loadingRef = useRef(false);
37		loadingRef.current = isLoading;
38		const queryRef = useRef<string | null>(null);
39		queryRef.current = query;
40	
41		const pending = useRef<{
42			query: string;
43			resolve: (refs: LobuRef[]) => void;
44		} | null>(null);
45	
46		const tryResolve = useCallback(() => {
47			const p = pending.current;
48			if (!p) return;
49			// Wait until the query state reflects this request AND the underlying data
50			// has finished loading — otherwise a cold cache (e.g. just after a thread
51			// reload) would resolve the pending request with an empty `refs`, leaving
52			// the popup permanently empty. `refs` filtering is synchronous, so once the
53			// data is present and the query matches, the results are final.
54			if (queryRef.current !== p.query) return;
55			if (loadingRef.current) return;
56			p.resolve(refsRef.current);
57			pending.current = null;
58		}, []);
59	
60		const searchRefs = useCallback(
61			(q: string) =>
62				new Promise<LobuRef[]>((resolve) => {
63					pending.current = { query: q, resolve };
64					// Always route through query state. Even when the query text is
65					// unchanged, the underlying data may have just arrived, so re-run the
66					// resolve check; if the query is new, setQuery kicks the memo + the
67					// settle-effect fulfils when refs update.
68					if (queryRef.current === q) {
69						tryResolve();
70					} else {
71						setQuery(q);
72					}
73				}),
74			[tryResolve],
75		);
76	
77		// When the search settles (results/loading/query changed), fulfil any pending
78		// request whose query now matches. These deps ARE the trigger — the callback
79		// reads them via refs, so biome can't see they must stay in the array.
80		// biome-ignore lint/correctness/useExhaustiveDependencies: deps are the intended re-run trigger
81		useEffect(() => {
82			tryResolve();
83		}, [refs, isLoading, query, tryResolve]);
84	
85		return searchRefs;
86	}
